const programs=[
 {id:1,title:'그림책 속으로, 가족 낭독 극장',source:'도봉문화정보도서관',type:'도서관',age:'가족',category:'독서',date:'10.17 (토) 14:00',place:'도봉문화정보도서관 1층',deadline:2,free:true,icon:'📚',desc:'아이와 부모가 함께 그림책을 읽고 짧은 낭독극을 완성하는 주말 프로그램입니다.'},
 {id:2,title:'알록달록 가을 숲 미술 놀이터',source:'도봉문화재단',type:'문화재단',age:'유아',category:'미술',date:'10.18 (일) 11:00',place:'평화문화진지 문화동',deadline:4,free:false,icon:'🎨',desc:'가을의 색과 질감을 관찰하고 자연 재료로 나만의 작은 숲을 만들어 봅니다.'},
 {id:3,title:'별별 우주 실험실: 달의 비밀',source:'쌍문채움도서관',type:'도서관',age:'초등',category:'과학',date:'10.24 (토) 15:00',place:'쌍문채움도서관 배움실',deadline:1,free:true,icon:'🚀',desc:'달의 모양이 달라지는 이유를 간단한 실험과 만들기를 통해 알아봅니다.'},
 {id:4,title:'엄마 아빠와 만드는 작은 정원',source:'도봉구청 교육지원과',type:'공공시설',age:'가족',category:'체험',date:'10.25 (일) 10:30',place:'초안산 생태공원',deadline:6,free:true,icon:'🌱',desc:'가족이 함께 계절 식물을 심고 돌보는 방법을 배우는 야외 생태 체험입니다.'},
 {id:5,title:'말랑말랑 클레이 동물 친구들',source:'도봉아이나라도서관',type:'도서관',age:'유아',category:'미술',date:'10.28 (수) 16:00',place:'도봉아이나라도서관',deadline:8,free:true,icon:'🐻',desc:'그림책 속 동물을 관찰한 뒤 다양한 색의 클레이로 캐릭터를 표현합니다.'},
 {id:6,title:'우리 동네 어린이 탐험대',source:'도봉구 마을사회적경제지원센터',type:'공공시설',age:'초등',category:'체험',date:'10.31 (토) 13:00',place:'창동 일대',deadline:3,free:false,icon:'🧭',desc:'지도를 들고 동네의 숨은 장소를 찾아 미션을 해결하는 어린이 탐방 활동입니다.'}
];
let saved=new Set(JSON.parse(localStorage.getItem('dobong-saved')||'[]'));let mode='all';let quick='all';
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);
function render(){let q=$('#search').value.trim().toLowerCase(),age=$('#age').value,cat=$('#category').value,place=$('#place').value;let list=programs.filter(p=>(mode!=='saved'||saved.has(p.id))&&(mode!=='weekend'||p.date.includes('토')||p.date.includes('일'))&&(quick!=='weekend'||p.date.includes('토')||p.date.includes('일'))&&(quick!=='soon'||p.deadline<=3)&&(quick!=='free'||p.free)&&(age==='all'||p.age===age)&&(cat==='all'||p.category===cat)&&(place==='all'||p.type===place)&&(`${p.title} ${p.source}`.toLowerCase().includes(q)));if($('#sort').value==='deadline')list.sort((a,b)=>a.deadline-b.deadline);if($('#sort').value==='date')list.sort((a,b)=>a.id-b.id);$('#resultCount').textContent=`${list.length}개의 프로그램`;$('#savedCount').textContent=saved.size;$('#listTitle').textContent=mode==='saved'?'찜한 프로그램':mode==='weekend'?'이번 주말 프로그램':'도봉구 프로그램';$('#programGrid').innerHTML=list.map(p=>`<article class="card" data-id="${p.id}"><div class="card-top"><span class="source">${p.source}</span><button class="heart ${saved.has(p.id)?'saved':''}" data-save="${p.id}" aria-label="찜하기">${saved.has(p.id)?'♥':'♡'}</button></div><h3>${p.title}</h3><ul class="meta"><li><b>일시</b>${p.date}</li><li><b>대상</b>${p.age}</li><li><b>장소</b>${p.place}</li></ul><div class="tags"><span class="tag">${p.category}</span><span class="tag ${p.free?'free':''}">${p.free?'무료':'재료비 있음'}</span>${p.deadline<=3?`<span class="tag deadline">마감 D-${p.deadline}</span>`:''}</div><div class="card-foot"><small>${p.type}</small><b>자세히 보기 →</b></div></article>`).join('');$('#empty').style.display=list.length?'none':'block'}
function save(id){saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem('dobong-saved',JSON.stringify([...saved]));render()}
function openDetail(p){$('#drawerContent').innerHTML=`<div class="big-icon">${p.icon}</div><span class="source">${p.source}</span><h2>${p.title}</h2><p>${p.desc}</p><div class="detail-box"><div><b>일시</b>${p.date}</div><div><b>대상</b>${p.age} 어린이</div><div><b>장소</b>${p.place}</div><div><b>비용</b>${p.free?'무료':'재료비 별도'}</div><div><b>신청</b>마감 D-${p.deadline}</div></div><a class="apply" href="#" onclick="event.preventDefault();showToast('포트폴리오 예시 프로그램입니다')">공식 사이트에서 신청하기</a><p class="demo-note">실제 서비스에서는 기관의 공식 신청 페이지로 연결됩니다.</p>`;$('#drawer').classList.add('open');$('#backdrop').classList.add('open');$('#drawer').setAttribute('aria-hidden','false')}
function closeDrawer(){$('#drawer').classList.remove('open');$('#backdrop').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true')}
window.showToast=t=>{let el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)};
$('#programGrid').addEventListener('click',e=>{let b=e.target.closest('[data-save]');if(b){e.stopPropagation();save(+b.dataset.save);return}let c=e.target.closest('.card');if(c)openDetail(programs.find(p=>p.id===+c.dataset.id))});
$('#search').addEventListener('input',render);['age','category','place','sort'].forEach(id=>$('#'+id).addEventListener('change',render));
$$('.chip').forEach(b=>b.addEventListener('click',()=>{$$('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');quick=b.dataset.value;render()}));
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>{$$('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');mode=b.dataset.view;render();$('.sidebar').classList.remove('mobile-open')}));
$$('.district').forEach(b=>b.addEventListener('click',()=>{if(!b.classList.contains('active'))showToast('다음 업데이트에서 만나요! 지금은 도봉구를 운영 중이에요.')}));
$('#drawerClose').addEventListener('click',closeDrawer);$('#backdrop').addEventListener('click',closeDrawer);$('#notifyBtn').addEventListener('click',()=>showToast('새 프로그램 알림을 신청했어요'));$('#childBtn').addEventListener('click',()=>showToast('봄이의 관심사 설정은 준비 중이에요'));$('#filterToggle').addEventListener('click',()=>$('#filters').classList.toggle('open'));$('#menuBtn').addEventListener('click',()=>$('.sidebar').classList.toggle('mobile-open'));render();
